-- Single development baseline. No historical upgrade chain.
CREATE TABLE agreement_versions ( id TEXT PRIMARY KEY, agreement_id TEXT NOT NULL REFERENCES agreements(id) ON DELETE CASCADE, version INTEGER NOT NULL CHECK (version >= 1), framework_id TEXT NOT NULL REFERENCES frameworks(id), code TEXT NOT NULL, name TEXT NOT NULL, amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), valid_from TEXT NOT NULL, valid_to TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','paused','expired')), reason TEXT, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, UNIQUE(agreement_id, version) );
CREATE TABLE agreements ( id TEXT PRIMARY KEY, framework_id TEXT NOT NULL REFERENCES frameworks(id), code TEXT NOT NULL COLLATE NOCASE UNIQUE, name TEXT NOT NULL, amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), valid_from TEXT NOT NULL, valid_to TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('active','paused','expired')), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (valid_from <= valid_to) );
CREATE TABLE alert_events ( id TEXT PRIMARY KEY, rule_key TEXT NOT NULL, rule_version INTEGER NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, period_key TEXT NOT NULL, severity TEXT NOT NULL CHECK (severity IN ('info','warning','critical')), state TEXT NOT NULL CHECK (state IN ('active','resolved')), unique_event_key TEXT NOT NULL UNIQUE, message TEXT NOT NULL, first_seen_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, resolved_at TEXT );
CREATE TABLE analysis_rules ( id TEXT PRIMARY KEY, version INTEGER NOT NULL UNIQUE CHECK (version >= 1), mode TEXT NOT NULL CHECK (mode IN ('ratio','gap')), threshold_basis_points INTEGER NOT NULL CHECK (threshold_basis_points >= 0 AND threshold_basis_points <= 10000), effective_from TEXT NOT NULL, created_by TEXT REFERENCES members(id), created_at TEXT NOT NULL );
CREATE TABLE annual_milestones ( id TEXT PRIMARY KEY, business_year INTEGER NOT NULL CHECK (business_year BETWEEN 2000 AND 2200), title TEXT NOT NULL, owner TEXT, project_id TEXT REFERENCES projects(id), date_precision TEXT NOT NULL CHECK (date_precision IN ('month','day','unknown')), month INTEGER CHECK (month BETWEEN 1 AND 12), specific_date TEXT, lead_days_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','completed')), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK ( (date_precision='month' AND month IS NOT NULL AND specific_date IS NULL) OR (date_precision='day' AND month IS NOT NULL AND specific_date IS NOT NULL) OR (date_precision='unknown' AND month IS NULL AND specific_date IS NULL) ) );
CREATE TABLE attachments ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), object_type TEXT NOT NULL CHECK (object_type IN ('project','release','implementation','settlement')), object_id TEXT NOT NULL, r2_key TEXT NOT NULL UNIQUE, file_name TEXT NOT NULL, content_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK (size_bytes >= 0), uploaded_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, deleted_at TEXT );
CREATE TABLE audit_events ( id TEXT PRIMARY KEY, actor_member_id TEXT REFERENCES members(id), action TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL );
CREATE TABLE auth_sessions ( id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, session_version INTEGER NOT NULL CHECK (session_version >= 1), created_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, expires_at TEXT NOT NULL, revoked_at TEXT );
CREATE TABLE backup_chunks ( id TEXT PRIMARY KEY, backup_run_id TEXT NOT NULL REFERENCES backup_runs(id) ON DELETE CASCADE, table_name TEXT NOT NULL, chunk_index INTEGER NOT NULL CHECK (chunk_index >= 0), r2_key TEXT NOT NULL UNIQUE, row_count INTEGER NOT NULL CHECK (row_count >= 0), sha256 TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(backup_run_id,table_name,chunk_index) );
CREATE TABLE backup_runs ( id TEXT PRIMARY KEY, backup_date TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('daily','monthly')), status TEXT NOT NULL CHECK (status IN ('pending','running','completed','failed')), current_table_index INTEGER NOT NULL DEFAULT 0 CHECK (current_table_index >= 0), cursor_rowid INTEGER NOT NULL DEFAULT 0 CHECK (cursor_rowid >= 0), manifest_key TEXT, chunk_count INTEGER NOT NULL DEFAULT 0 CHECK (chunk_count >= 0), error TEXT, started_at TEXT, completed_at TEXT, verified_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(backup_date,kind) );
CREATE TABLE budget_allocations ( id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES project_budgets(id) ON DELETE CASCADE, agreement_id TEXT NOT NULL REFERENCES agreements(id), amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), created_at TEXT NOT NULL, UNIQUE(budget_id, agreement_id) );
CREATE TABLE budget_version_allocations ( id TEXT PRIMARY KEY, budget_version_id TEXT NOT NULL REFERENCES budget_versions(id) ON DELETE CASCADE, agreement_id TEXT NOT NULL REFERENCES agreements(id), amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), created_at TEXT NOT NULL, UNIQUE(budget_version_id, agreement_id) );
CREATE TABLE budget_versions ( id TEXT PRIMARY KEY, budget_id TEXT NOT NULL REFERENCES project_budgets(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, framework_id TEXT NOT NULL REFERENCES frameworks(id), budget_version INTEGER NOT NULL CHECK (budget_version >= 1), total_amount_fen INTEGER NOT NULL CHECK (total_amount_fen >= 0), note TEXT, confirmed_by TEXT NOT NULL REFERENCES members(id), confirmed_at TEXT NOT NULL, UNIQUE(budget_id, budget_version) );
CREATE TABLE category_cost_allocations ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, cost_line_id TEXT NOT NULL REFERENCES project_cost_lines(id) ON DELETE CASCADE, reserve_category_id TEXT NOT NULL REFERENCES reserve_categories(id), amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), created_at TEXT NOT NULL, UNIQUE(cost_line_id, reserve_category_id) );
CREATE TABLE category_mappings ( id TEXT PRIMARY KEY, demand_category_key TEXT NOT NULL COLLATE NOCASE UNIQUE, reserve_category_id TEXT NOT NULL REFERENCES reserve_categories(id), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE demand_allocations ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, demand_material_id TEXT NOT NULL REFERENCES demand_materials(id), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled > 0), created_at TEXT NOT NULL, UNIQUE(project_id, demand_material_id) );
CREATE TABLE demand_categories ( category_key TEXT PRIMARY KEY, label TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE demand_materials ( id TEXT PRIMARY KEY, demand_id TEXT NOT NULL REFERENCES demands(id) ON DELETE CASCADE, raw_model TEXT NOT NULL, material_id TEXT REFERENCES materials(id), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled > 0), unit TEXT, created_at TEXT NOT NULL , source_import_row_id TEXT REFERENCES import_rows(id), created_by TEXT REFERENCES members(id), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1));
CREATE TABLE demand_source_rows ( id TEXT PRIMARY KEY, demand_id TEXT NOT NULL REFERENCES demands(id) ON DELETE CASCADE, import_row_id TEXT NOT NULL REFERENCES import_rows(id), source_key TEXT NOT NULL UNIQUE, file_sha256 TEXT NOT NULL, file_name TEXT NOT NULL, sheet_name TEXT NOT NULL, source_row_number INTEGER NOT NULL CHECK (source_row_number >= 1), raw_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(demand_id, import_row_id) );
CREATE TABLE "demands" ( id TEXT PRIMARY KEY, source_type TEXT NOT NULL DEFAULT 'import' CHECK (source_type IN ('import', 'manual')), source_key TEXT NOT NULL UNIQUE, source_batch_id TEXT REFERENCES import_batches(id), source_file_sha256 TEXT, source_file_name TEXT, source_sheet TEXT, source_row_number INTEGER CHECK (source_row_number IS NULL OR source_row_number >= 1), sequence_no TEXT NOT NULL, business_year INTEGER, voltage_raw TEXT NOT NULL, voltage_verified TEXT, line_name TEXT NOT NULL, section_text TEXT NOT NULL, category_key TEXT, owner TEXT, business_signature TEXT NOT NULL, raw_json TEXT NOT NULL, extra_json TEXT NOT NULL DEFAULT '{}', version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, voltage_level_id TEXT REFERENCES voltage_levels(id) ON DELETE RESTRICT, line_id TEXT REFERENCES transmission_lines(id) ON DELETE RESTRICT, location_type TEXT, start_tower_id TEXT REFERENCES transmission_towers(id) ON DELETE RESTRICT, end_tower_id TEXT REFERENCES transmission_towers(id) ON DELETE RESTRICT, CHECK ( (source_type = 'import' AND source_batch_id IS NOT NULL AND source_file_sha256 IS NOT NULL AND source_file_name IS NOT NULL AND source_sheet IS NOT NULL AND source_row_number IS NOT NULL) OR (source_type = 'manual' AND source_batch_id IS NULL AND source_file_sha256 IS NULL AND source_file_name IS NULL AND source_sheet IS NULL AND source_row_number IS NULL) ) );
CREATE TABLE dictionary_items ( id TEXT PRIMARY KEY, dictionary_key TEXT NOT NULL, item_key TEXT NOT NULL, label TEXT NOT NULL, value_json TEXT, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), sort_order INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(dictionary_key, item_key) );
CREATE TABLE field_definitions ( field_key TEXT PRIMARY KEY, label TEXT NOT NULL, data_type TEXT NOT NULL CHECK (data_type IN ('text', 'integer', 'quantity', 'year')), required INTEGER NOT NULL DEFAULT 0 CHECK (required IN (0, 1)), sort_order INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE financial_entries ( id TEXT PRIMARY KEY, framework_id TEXT NOT NULL REFERENCES frameworks(id), project_id TEXT NOT NULL REFERENCES projects(id), entry_type TEXT NOT NULL CHECK (entry_type IN ('budget_occurrence','actual_cost')), business_date TEXT NOT NULL, amount_fen INTEGER NOT NULL, note TEXT, reverses_entry_id TEXT REFERENCES financial_entries(id), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, CHECK (amount_fen <> 0) );
CREATE TABLE financial_entry_allocations ( id TEXT PRIMARY KEY, financial_entry_id TEXT NOT NULL REFERENCES financial_entries(id) ON DELETE CASCADE, agreement_id TEXT NOT NULL REFERENCES agreements(id), amount_fen INTEGER NOT NULL, created_at TEXT NOT NULL, CHECK (amount_fen <> 0), UNIQUE(financial_entry_id, agreement_id) );
CREATE TABLE framework_versions ( id TEXT PRIMARY KEY, framework_id TEXT NOT NULL REFERENCES frameworks(id) ON DELETE CASCADE, version INTEGER NOT NULL CHECK (version >= 1), code TEXT NOT NULL, name TEXT NOT NULL, total_amount_fen INTEGER NOT NULL CHECK (total_amount_fen >= 0), annual_target_fen INTEGER CHECK (annual_target_fen IS NULL OR annual_target_fen >= 0), start_date TEXT NOT NULL, end_date TEXT NOT NULL, reason TEXT, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, UNIQUE(framework_id, version) );
CREATE TABLE frameworks ( id TEXT PRIMARY KEY, code TEXT NOT NULL COLLATE NOCASE UNIQUE, name TEXT NOT NULL, total_amount_fen INTEGER NOT NULL CHECK (total_amount_fen >= 0), annual_target_fen INTEGER CHECK (annual_target_fen IS NULL OR annual_target_fen >= 0), start_date TEXT NOT NULL, end_date TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK (start_date <= end_date) );
CREATE TABLE idempotency_records ( idempotency_key TEXT PRIMARY KEY, actor_member_id TEXT NOT NULL REFERENCES members(id), operation TEXT NOT NULL, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, status_code INTEGER NOT NULL, created_at TEXT NOT NULL );
CREATE TABLE implementation_lines ( id TEXT PRIMARY KEY, implementation_id TEXT NOT NULL REFERENCES implementation_records(id) ON DELETE CASCADE, project_id TEXT REFERENCES projects(id), release_line_id TEXT REFERENCES release_lines(id), demand_material_id TEXT REFERENCES demand_materials(id), description TEXT, unit TEXT, completed_quantity_scaled INTEGER NOT NULL CHECK (completed_quantity_scaled > 0), actual_used_quantity_scaled INTEGER CHECK (actual_used_quantity_scaled IS NULL OR actual_used_quantity_scaled >= 0), created_at TEXT NOT NULL, CHECK ( (release_line_id IS NOT NULL AND project_id IS NOT NULL AND demand_material_id IS NOT NULL) OR (release_line_id IS NULL) ) );
CREATE TABLE implementation_records ( id TEXT PRIMARY KEY, project_id TEXT REFERENCES projects(id), historical INTEGER NOT NULL DEFAULT 0 CHECK (historical IN (0,1)), record_date TEXT NOT NULL, personnel TEXT, note TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK ((historical=0 AND project_id IS NOT NULL) OR historical=1) );
CREATE TABLE import_batches ( id TEXT PRIMARY KEY, file_name TEXT NOT NULL, file_sha256 TEXT NOT NULL COLLATE NOCASE UNIQUE, file_type TEXT NOT NULL CHECK (file_type IN ('xlsx', 'csv')), mapping_json TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'validating', 'review', 'ready', 'publishing', 'published')), uploaded_rows INTEGER NOT NULL DEFAULT 0 CHECK (uploaded_rows >= 0), valid_rows INTEGER NOT NULL DEFAULT 0 CHECK (valid_rows >= 0), error_rows INTEGER NOT NULL DEFAULT 0 CHECK (error_rows >= 0), warning_rows INTEGER NOT NULL DEFAULT 0 CHECK (warning_rows >= 0), published_rows INTEGER NOT NULL DEFAULT 0 CHECK (published_rows >= 0), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, published_at TEXT );
CREATE TABLE import_mapping_templates ( id TEXT PRIMARY KEY, name TEXT NOT NULL COLLATE NOCASE UNIQUE, mapping_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE import_rows ( id TEXT PRIMARY KEY, batch_id TEXT NOT NULL REFERENCES import_batches(id) ON DELETE CASCADE, chunk_index INTEGER NOT NULL CHECK (chunk_index >= 0), sheet_name TEXT NOT NULL, source_row_number INTEGER NOT NULL CHECK (source_row_number >= 1), source_key TEXT NOT NULL UNIQUE, raw_json TEXT NOT NULL, normalized_json TEXT, errors_json TEXT NOT NULL DEFAULT '[]', warnings_json TEXT NOT NULL DEFAULT '[]', row_status TEXT NOT NULL DEFAULT 'uploaded' CHECK (row_status IN ('uploaded', 'valid', 'error', 'published')), published_demand_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(batch_id, sheet_name, source_row_number) );
CREATE TABLE master_data_guards ( id INTEGER PRIMARY KEY CHECK(id=1), invalid_grid_location INTEGER NOT NULL DEFAULT 1 CONSTRAINT INVALID_GRID_LOCATION CHECK(invalid_grid_location=1), voltage_parent INTEGER NOT NULL DEFAULT 1 CONSTRAINT VOLTAGE_LEVEL_NOT_FOUND CHECK(voltage_parent=1), line_parent INTEGER NOT NULL DEFAULT 1 CONSTRAINT LINE_NOT_FOUND CHECK(line_parent=1), line_reference INTEGER NOT NULL DEFAULT 1 CONSTRAINT LINE_LOCATION_IN_USE CHECK(line_reference=1), tower_reference INTEGER NOT NULL DEFAULT 1 CONSTRAINT TOWER_LOCATION_IN_USE CHECK(tower_reference=1), voltage_reference INTEGER NOT NULL DEFAULT 1 CONSTRAINT VOLTAGE_LOCATION_IN_USE CHECK(voltage_reference=1) );
CREATE TABLE material_supply_events ( id TEXT PRIMARY KEY, task_material_requirement_id TEXT NOT NULL REFERENCES task_material_requirements(id), stage TEXT NOT NULL CHECK (stage IN ('reported','shipped','arrived')), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled > 0), event_date TEXT NOT NULL, note TEXT, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL );
CREATE TABLE materials ( id TEXT PRIMARY KEY, code TEXT COLLATE NOCASE UNIQUE, name TEXT NOT NULL, model TEXT NOT NULL COLLATE NOCASE, unit TEXT NOT NULL COLLATE NOCASE, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(model, unit) );
CREATE TABLE member_scopes ( id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, scope_type TEXT NOT NULL CHECK (scope_type IN ('all', 'framework', 'project')), scope_id TEXT, created_at TEXT NOT NULL, CHECK ((scope_type = 'all' AND scope_id IS NULL) OR (scope_type != 'all' AND scope_id IS NOT NULL)), UNIQUE(member_id, scope_type, scope_id) );
CREATE TABLE members ( id TEXT PRIMARY KEY, username TEXT NOT NULL COLLATE NOCASE UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('admin', 'project_manager', 'implementation', 'finance', 'readonly')), enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), credential_salt TEXT NOT NULL, credential_verifier TEXT NOT NULL, credential_algorithm TEXT NOT NULL CHECK (credential_algorithm = 'argon2id-v1'), credential_params_json TEXT NOT NULL, must_change_password INTEGER NOT NULL DEFAULT 1 CHECK (must_change_password IN (0, 1)), session_version INTEGER NOT NULL DEFAULT 1 CHECK (session_version >= 1), failed_login_count INTEGER NOT NULL DEFAULT 0 CHECK (failed_login_count >= 0), locked_until TEXT, last_failed_login_at TEXT, credential_changed_at TEXT NOT NULL, invited_at TEXT, first_login_at TEXT, last_login_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE monthly_plans ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, business_year INTEGER NOT NULL CHECK (business_year BETWEEN 2000 AND 2200), month INTEGER NOT NULL CHECK (month BETWEEN 1 AND 12), target_amount_fen INTEGER NOT NULL CHECK (target_amount_fen >= 0), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,business_year,month) );
CREATE TABLE notification_contacts ( id TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id) ON DELETE CASCADE, address TEXT NOT NULL COLLATE NOCASE, verified_at TEXT, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(member_id,address) );
CREATE TABLE notification_outbox ( id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES alert_events(id) ON DELETE CASCADE, recipient TEXT NOT NULL, notification_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK (status IN ('pending','leased','sent','failed','unknown')), lease_token TEXT, lease_until TEXT, attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0), next_attempt_at TEXT NOT NULL, last_error TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE project_budgets ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, total_amount_fen INTEGER NOT NULL CHECK (total_amount_fen >= 0), note TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','confirmed')), budget_version INTEGER NOT NULL DEFAULT 0 CHECK (budget_version >= 0), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE project_cost_lines ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('material', 'construction', 'other')), demand_allocation_id TEXT REFERENCES demand_allocations(id) ON DELETE CASCADE, label TEXT NOT NULL, unit_price_scaled INTEGER CHECK (unit_price_scaled IS NULL OR unit_price_scaled >= 0), amount_fen INTEGER CHECK (amount_fen IS NULL OR amount_fen >= 0), price_source TEXT, price_date TEXT, tax_inclusive INTEGER CHECK (tax_inclusive IS NULL OR tax_inclusive IN (0, 1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK ( (kind = 'material' AND demand_allocation_id IS NOT NULL) OR (kind IN ('construction', 'other') AND demand_allocation_id IS NULL AND unit_price_scaled IS NULL AND amount_fen IS NOT NULL) ), UNIQUE(project_id, demand_allocation_id) );
CREATE TABLE project_demand_links ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, demand_id TEXT NOT NULL REFERENCES demands(id), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, UNIQUE(project_id, demand_id) );
CREATE TABLE project_material_requirements ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, material_id TEXT REFERENCES materials(id), model TEXT NOT NULL, unit TEXT NOT NULL, required_quantity_scaled INTEGER NOT NULL CHECK (required_quantity_scaled > 0), unit_price_scaled INTEGER CHECK (unit_price_scaled IS NULL OR unit_price_scaled >= 0), amount_fen INTEGER CHECK (amount_fen IS NULL OR amount_fen >= 0), reserve_category_id TEXT REFERENCES reserve_categories(id), active INTEGER NOT NULL DEFAULT 1 CHECK (active IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE project_material_revisions ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, project_version INTEGER NOT NULL CHECK (project_version >= 1), reason TEXT NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL );
CREATE TABLE project_releases ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL UNIQUE REFERENCES projects(id), release_date TEXT NOT NULL, note TEXT, project_version_snapshot INTEGER NOT NULL CHECK (project_version_snapshot >= 1), reserve_version_snapshot INTEGER NOT NULL CHECK (reserve_version_snapshot >= 1), snapshot_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL );
CREATE TABLE project_tasks ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), project_release_id TEXT NOT NULL REFERENCES project_releases(id), name TEXT NOT NULL, description TEXT, scope_text TEXT, owner TEXT, planned_date TEXT, planned_quantity_scaled INTEGER NOT NULL CHECK (planned_quantity_scaled > 0), unit TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), implementation_version INTEGER NOT NULL DEFAULT 1 CHECK (implementation_version >= 1), settlement_version INTEGER NOT NULL DEFAULT 1 CHECK (settlement_version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE project_versions ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, reserve_version INTEGER NOT NULL CHECK (reserve_version >= 1), snapshot_json TEXT NOT NULL, known_amount_fen INTEGER NOT NULL CHECK (known_amount_fen >= 0), missing_price_count INTEGER NOT NULL CHECK (missing_price_count >= 0), completeness_basis_points INTEGER NOT NULL CHECK (completeness_basis_points BETWEEN 0 AND 10000), reason TEXT, confirmed_by TEXT NOT NULL REFERENCES members(id), confirmed_at TEXT NOT NULL, UNIQUE(project_id, reserve_version) );
CREATE TABLE projects ( id TEXT PRIMARY KEY, name TEXT NOT NULL, business_year INTEGER CHECK (business_year IS NULL OR (business_year >= 1900 AND business_year <= 2200)), owner TEXT, status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'confirmed')), reserve_version INTEGER NOT NULL DEFAULT 0 CHECK (reserve_version >= 0), framework_id TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE release_batches ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), release_date TEXT NOT NULL, note TEXT, project_version_snapshot INTEGER NOT NULL CHECK (project_version_snapshot >= 1), reserve_version_snapshot INTEGER NOT NULL CHECK (reserve_version_snapshot >= 0), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL );
CREATE TABLE release_lines ( id TEXT PRIMARY KEY, release_batch_id TEXT NOT NULL REFERENCES release_batches(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id), demand_material_id TEXT NOT NULL REFERENCES demand_materials(id), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled > 0), snapshot_json TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(release_batch_id, demand_material_id) );
CREATE TABLE report_snapshots ( id TEXT PRIMARY KEY, framework_id TEXT NOT NULL REFERENCES frameworks(id), business_month TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision >= 1), data_cutoff_date TEXT NOT NULL, rule_version INTEGER NOT NULL, rule_json TEXT NOT NULL, snapshot_json TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, UNIQUE(framework_id,business_month,revision) );
CREATE TABLE reserve_categories ( id TEXT PRIMARY KEY, category_key TEXT NOT NULL COLLATE NOCASE UNIQUE, label TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1)), version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE settings_versions ( id TEXT PRIMARY KEY, setting_key TEXT NOT NULL, version INTEGER NOT NULL CHECK (version >= 1), value_json TEXT NOT NULL, effective_from TEXT NOT NULL, created_by TEXT REFERENCES members(id), created_at TEXT NOT NULL, UNIQUE(setting_key, version) );
CREATE TABLE settlement_agreement_allocations ( id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlements(id) ON DELETE CASCADE, agreement_id TEXT NOT NULL REFERENCES agreements(id), amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), created_at TEXT NOT NULL, UNIQUE(settlement_id, agreement_id) );
CREATE TABLE settlement_coverage ( id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlements(id) ON DELETE CASCADE, project_id TEXT NOT NULL REFERENCES projects(id), demand_material_id TEXT NOT NULL REFERENCES demand_materials(id), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled > 0), created_at TEXT NOT NULL, UNIQUE(settlement_id, demand_material_id) );
CREATE TABLE settlements ( id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), settlement_date TEXT NOT NULL, amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), final INTEGER NOT NULL DEFAULT 0 CHECK (final IN (0,1)), note TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), voided_at TEXT, voided_by TEXT REFERENCES members(id), void_reason TEXT, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK ((voided_at IS NULL AND voided_by IS NULL AND void_reason IS NULL) OR (voided_at IS NOT NULL AND voided_by IS NOT NULL AND void_reason IS NOT NULL)) );
CREATE TABLE task_demand_scopes ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES project_tasks(id) ON DELETE CASCADE, demand_id TEXT NOT NULL REFERENCES demands(id), planned_quantity_scaled INTEGER NOT NULL CHECK (planned_quantity_scaled > 0), created_at TEXT NOT NULL, UNIQUE(task_id, demand_id) );
CREATE TABLE task_implementation_records ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES project_tasks(id), record_date TEXT NOT NULL, completed_quantity_scaled INTEGER NOT NULL CHECK (completed_quantity_scaled > 0), note TEXT, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL );
CREATE TABLE task_implementation_scope_lines ( id TEXT PRIMARY KEY, implementation_id TEXT NOT NULL REFERENCES task_implementation_records(id) ON DELETE CASCADE, task_demand_scope_id TEXT NOT NULL REFERENCES task_demand_scopes(id), completed_quantity_scaled INTEGER NOT NULL CHECK (completed_quantity_scaled > 0), created_at TEXT NOT NULL, UNIQUE(implementation_id, task_demand_scope_id) );
CREATE TABLE task_material_requirements ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES project_tasks(id) ON DELETE CASCADE, project_material_requirement_id TEXT REFERENCES project_material_requirements(id), material_id TEXT REFERENCES materials(id), model TEXT NOT NULL, unit TEXT NOT NULL, required_quantity_scaled INTEGER NOT NULL CHECK (required_quantity_scaled > 0), supply_version INTEGER NOT NULL DEFAULT 1 CHECK (supply_version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(task_id, project_material_requirement_id) );
CREATE TABLE task_material_usage_lines ( id TEXT PRIMARY KEY, implementation_id TEXT NOT NULL REFERENCES task_implementation_records(id) ON DELETE CASCADE, task_material_requirement_id TEXT NOT NULL REFERENCES task_material_requirements(id), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled >= 0), created_at TEXT NOT NULL, UNIQUE(implementation_id, task_material_requirement_id) );
CREATE TABLE task_settlement_agreement_allocations ( id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES task_settlements(id) ON DELETE CASCADE, agreement_id TEXT NOT NULL REFERENCES agreements(id), amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), created_at TEXT NOT NULL, UNIQUE(settlement_id, agreement_id) );
CREATE TABLE task_settlement_reminders ( task_id TEXT PRIMARY KEY REFERENCES project_tasks(id) ON DELETE CASCADE, first_implementation_date TEXT NOT NULL, due_date TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('open','closed')), final_settlement_id TEXT REFERENCES task_settlements(id), updated_at TEXT NOT NULL );
CREATE TABLE task_settlement_scope_lines ( id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES task_settlements(id) ON DELETE CASCADE, task_demand_scope_id TEXT NOT NULL REFERENCES task_demand_scopes(id), quantity_scaled INTEGER NOT NULL CHECK (quantity_scaled > 0), created_at TEXT NOT NULL, UNIQUE(settlement_id, task_demand_scope_id) );
CREATE TABLE task_settlements ( id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES project_tasks(id), settlement_date TEXT NOT NULL, coverage_quantity_scaled INTEGER NOT NULL CHECK (coverage_quantity_scaled > 0), amount_fen INTEGER NOT NULL CHECK (amount_fen >= 0), final INTEGER NOT NULL DEFAULT 0 CHECK (final IN (0,1)), note TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), voided_at TEXT, voided_by TEXT REFERENCES members(id), void_reason TEXT, created_by TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK ((voided_at IS NULL AND voided_by IS NULL AND void_reason IS NULL) OR (voided_at IS NOT NULL AND voided_by IS NOT NULL AND void_reason IS NOT NULL)) );
CREATE TABLE transmission_lines ( id TEXT PRIMARY KEY, voltage_level_id TEXT NOT NULL REFERENCES voltage_levels(id) ON DELETE RESTRICT, line_code TEXT, line_name TEXT NOT NULL, name_valid_from TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), tower_order_version INTEGER NOT NULL DEFAULT 1 CHECK (tower_order_version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
CREATE TABLE transmission_line_name_history ( id TEXT PRIMARY KEY, line_id TEXT NOT NULL REFERENCES transmission_lines(id) ON DELETE CASCADE, line_name TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT NOT NULL, changed_by TEXT NOT NULL REFERENCES members(id), change_reason TEXT, created_at TEXT NOT NULL, CHECK (valid_from < valid_to) );
CREATE TABLE transmission_towers ( id TEXT PRIMARY KEY, line_id TEXT NOT NULL REFERENCES transmission_lines(id) ON DELETE RESTRICT, tower_no TEXT NOT NULL, number_valid_from TEXT NOT NULL, sort_rank INTEGER NOT NULL, tower_type TEXT, enabled INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1 CHECK (version >= 1), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(line_id, sort_rank) );
CREATE TABLE transmission_tower_no_history ( id TEXT PRIMARY KEY, tower_id TEXT NOT NULL REFERENCES transmission_towers(id) ON DELETE CASCADE, line_id TEXT NOT NULL REFERENCES transmission_lines(id) ON DELETE RESTRICT, tower_no TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT NOT NULL, changed_by TEXT NOT NULL REFERENCES members(id), change_reason TEXT, created_at TEXT NOT NULL, CHECK (valid_from < valid_to) );
CREATE TABLE voltage_levels ( id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL UNIQUE, system_type TEXT NOT NULL, nominal_kv INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL );
